                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                x, y = stack.pop()
                comp.append((x, y))
                for nx, ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 2 and (nx,ny) not in seen:
                        seen.add((nx,ny))
                        stack.append((nx,ny))
            rs = [x for x, y in comp]
            cs = [y for x, y in comp]
            r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
            if (r1-r0+1 >= 3 and c1-c0+1 >= 3 and
                all(grid[r0][y] == grid[r1][y] == 2 for y in range(c0,c1+1)) and
                all(grid[x][c0] == grid[x][c1] == 2 for x in range(r0,r1+1))):
                rectangles.append((r0,r1,c0,c1))

    # Interior size identifies the fill color.
    color_for_side = {3: 8, 5: 4, 6: 3, 7: 2}
    for r0, r1, c0, c1 in rectangles:
